128	        Random rand = getRandomProvider().getRandom();
129	        Field field = getField();
130	        List<Location> adjacent = field.adjacentLocations(getLocation());
131	        for(Location loc : adjacent){
132	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
133	                Organism organism = (Organism) field.getObjectAt(loc);
134	                if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
135	                    // contracts the first contact disease it encounters amongst the adjacent animals
136	                    this.setDisease(organism.getDisease());
