122	    /**
123	     * Returns a random set of patches from getFreePatches() based on a given rate
124	     * getFreePatches() returns a list of size n, only (n*rate) random locations are returned
125	     * @param rateOfGeneration The rate
126	     */
127	    public List<Location> getRandomFreePatches(double rateOfGeneration)
128	    {
129	        Random rand = randomProvider.getRandom();
130	        List<Location> patches = getFreePatches();
131	        List<Location> randPatches = new ArrayList<>();
132	        for(int i=0; i<rateOfGeneration* patches.size(); i++)
133	        {
134	            Location selectedPatch = patches.get(rand.nextInt(patches.size()));
135	            randPatches.add(selectedPatch);
136	            for(Location loc : adjacentLocations(selectedPatch)){
137	                // avoids duplicates in the patches
138	                patches.remove(loc);
139	            }
140	        }
141	        return randPatches;
142	    }
