144	    /**
145	     * Gets the free patches in the field and returns them.
146	     * A 'patch' is a 3x3 square of locations, the locations in the list are the centers of said squares
147	     * Patches do not overlap, so the adjacent locations of one patch don't have common locations with
148	     * the adjacent locations of any other square
149	     *
150	     * @return The list of free patches in the field.
151	     */
152	    public List<Location> getFreePatches()
153	    {
154	        List<Location> res = new ArrayList<>();
155	        for(int i=0; i<field.length; i++){
156	            for(int j=0; j<field[1].length; j++){
157	                if (field[i][j] == null){
158	                    List<Location> nearby = adjacentLocations(new Location(i, j));
159	                    boolean allNulls = true;
160	                    for(Location loc : nearby){
161	                        if(getObjectAt(loc) != null){
162	                            allNulls = false;
163	                        }
164	                    }
165	                    if(allNulls){
166	                        res.add(new Location(i, j));
167	                    }
168	                }
169	            }
170	        }
171	
172	        return res;
173	    }
