177	     * @param location Get locations adjacent to this.
178	     * @return A list of free adjacent locations.
179	     */
180	    public List<Location> getFreeAdjacentLocations(Location location)
181	    {
182	        List<Location> free = new LinkedList<>();
183	        List<Location> adjacent = adjacentLocations(location);
184	        for(Location next : adjacent) {
185	            Object objectAtNext = getObjectAt(next);
186	            if(objectAtNext == null) {
187	                free.add(next);
188	            }
189	        }
190	        return free;
191	    }
