213	    /**
214	     * Returns adjacent locations in the field containing a certain class
215	     * For example, adjacentSpecies(location, Grass.class) returns the adjacent locations with Grass
216	     * @param location The location of an organism.
217	     * @param speciesClass The type of species.
218	     * @return adjacentSpecies A list of adjacent locations with the specified species 
219	     */
220	    public List<Location> adjacentLocationsWithSpecies(Location location, Class<?> speciesClass) {
221	        List<Location> free = adjacentLocations(location);
222	        List<Location> res = new ArrayList<>();
223	        for (Location loc : free) {
224	            if (getObjectAt(loc) != null && getObjectAt(loc).getClass()==speciesClass) {
225	                res.add(loc);
226	            }
227	        }
228	        return res;
229	    }
