231	    /**
232	     * Return a shuffled list of locations adjacent to the given one.
233	     * The list will not include the location itself.
234	     * All locations will lie within the grid.
235	     * @param location The location from which to generate adjacencies.
236	     * @return A list of locations adjacent to that given.
237	     */
238	    public List<Location> adjacentLocations(Location location)
239	    {
240	        assert location != null : "Null location passed to adjacentLocations";
241	        // The list of locations to be returned.
242	        List<Location> locations = new LinkedList<>();
243	        if(location != null) {
244	            int row = location.getRow();
245	            int col = location.getCol();
246	            for(int roffset = -1; roffset <= 1; roffset++) {
247	                int nextRow = row + roffset;
248	                if(nextRow >= 0 && nextRow < depth) {
249	                    for(int coffset = -1; coffset <= 1; coffset++) {
250	                        int nextCol = col + coffset;
251	                        // Exclude invalid locations and the original location.
252	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
253	                            locations.add(new Location(nextRow, nextCol));
254	                        }
255	                    }
256	                }
257	            }
258	            
259	            // Shuffle the list. Several other methods rely on the list
260	            // being in a random order.
261	            Collections.shuffle(locations, randomProvider.getRandom());
262	        }
263	        return locations;
264	    }
