  4	/**
  5	 * This class models grass.
  6	 * Grass can germinate,grow and get eaten by animals.
  7	 * @version 2022.03.02
  8	 */
  9	public class Grass extends Plant
 10	{
 11	    private static final int MAX_GROWTH_STAGES = 3;
 12	    private static final int DEFAULT_STEPS_PER_STAGE = 2;
 13	    private static final double BASE_GERMINATION_RATE = 0.1;
 14	    private static final double SUNNY_GERMINATION_RATE = 0.15;
 15	
 16	    private int foodValue;
 17	
 18	    /**
 19	     * Returns the food value of the grass.
 20	     * @return int The food value of the grass.
 21	     */
 22	    protected int getFoodValue()
 23	    {
 24	        return foodValue;
 25	    }
 26	
 27	    /**
 28	     * Creates grass with a random stage of growth.
 29	     * However, the maximum number of stages is fixed at 3,
 30	     * and the growth rate is fixed at 2 steps per stage.
 31	     *
 32	     * @param field The field currently occupied.
 33	     * @param location The location within the field.
 34	     */
 35	    public Grass(Field field, Location location)
 36	    {
 37	        super(field.getRandomProvider(), field, location);
 38	
 39	        numberOfStages = MAX_GROWTH_STAGES;
 40	        stepsPerStage = DEFAULT_STEPS_PER_STAGE;
 41	        stageOfGrowth = getRandomProvider().getRandom().nextInt(numberOfStages);
 42	        foodValue = stageOfGrowth;
 43	
 44	    }
 45	
 46	
 47	    /**
 48	     * Make the grass act.
 49	     * The germination rate of grass is affected by weather.
 50	     * @param newGrass To store the newly germinated grass.
 51	     * @param environment The environment that the grass resides in.
 52	     */
 53	    public void act(List<Actor> newGrass, Environment environment)
 54	    {
 55	        Random rand = getRandomProvider().getRandom();
 56	        if(isAlive()
 57	                && environment.getTime().isDay()
 58	                && rand.nextDouble() <= getGerminationRate(environment)
 59	                && environment.getWeather().getCurrentWeather() != WeatherType.CLOUDY) {
 60	            germinate(newGrass);
 61	        }
 62	    }
 63	
 64	    /**
 65	     * Check whether this grass is to germinate at this step.
 66	     * New grass will be made into free adjacent locations.
 67	     * @param newGrass A list to return newly made grass.
 68	     */
 69	    protected void germinate(List<Actor> newGrass)
 70	    {
 71	        // New grass are made into adjacent locations.
 72	        // Get a list of adjacent free locations.
 73	        Field field = getField();
 74	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
 75	        for(int b = 0; b < free.size(); b++) {
 76	            Location loc = free.remove(0);
 77	            Grass young = field.getOrganismFactory().createOffspring(Grass.class, field, loc);
 78	            newGrass.add(young);
 79	        }
 80	    }
 81	
 82	    /**
 83	     * Increment the stage of growth of grass
 84	     * Incrementing the growth also increases the food level by 1
 85	     * @return true If the grass grows.
 86	     * @return false If the grass doesn't grow.
 87	     */
 88	    public boolean incrementGrowth()
 89	    {
 90	        if(super.incrementGrowth()) {
 91	            foodValue++;
 92	            return true;
 93	        }
 94	        return false;
 95	    }
 96	
 97	    private double getGerminationRate(Environment environment)
 98	    {
 99	        if(environment.getWeather().getCurrentWeather() == WeatherType.SUNNY) {
100	            return SUNNY_GERMINATION_RATE;
101	        }
102	        return BASE_GERMINATION_RATE;
103	    }
